def seal_map_history_journal_bundle(
    evidences: object, key: object, *, state: object = None
) -> "BitMapHistoryJournalBundle":
    """Audit a contiguous journal segment chain and seal it as a bundle.

    ``evidences`` must be a non-empty iterable of
    :class:`BitMapHistoryEvidence` instances or their canonical
    :meth:`BitMapHistoryEvidence.to_bytes` encodings — a non-iterable or a
    wrong-typed item raises :class:`TypeError`, an empty sequence or a
    malformed item raises :class:`ValueError`. ``key`` must be non-empty
    ``bytes`` — a non-bytes value raises :class:`TypeError`, an empty value
    :class:`ValueError``. ``state`` is keyword-only: ``None`` (the default)
    starts the chain from no journal state at all, so the bundle's ``start``
    is the empty bytes; otherwise it must be a
    :class:`BitMapHistoryJournalState` or its canonical
    :meth:`BitMapHistoryJournalState.to_bytes` encoding (any other type
    raises :class:`TypeError`), checked at both MAC layers exactly as
    :class:`BitMapHistoryJournalAuditor` checks it. Every segment is
    replayed in order through a :class:`BitMapHistoryJournalAuditor` — a
    MAC mismatch, a failed carried update or a broken chain raises
    :class:`ValueError` — and only on success is the bundle produced: the
    canonical evidence encodings in chain order, ``end`` the canonical
    encoding of the final journal state and ``mac`` computed as
    ``HMAC-SHA256(key, b"NPBJ3" + C)``. Sealing touches no auditor state
    beyond the throwaway replay.
    """
