        items = list(evidences)  # type: ignore[arg-type]
    except TypeError:
        raise TypeError(
            "evidences must be an iterable of BitMapHistoryEvidence instances"
            " or their canonical bytes"
        ) from None
    if not items:
        raise ValueError("evidences must be a non-empty iterable")
    if not isinstance(key, bytes):
        raise TypeError("key must be bytes")
    if not key:
        raise ValueError("key must be non-empty")
    auditor = BitMapHistoryJournalAuditor(key, state=state)
    coerced = [
        _coerce_bit_map_history_evidence(item, "evidences items")
        for item in items
    ]
    for evidence in coerced:
        auditor.audit(evidence)
    final = auditor.state
    assert final is not None  # guaranteed: items is non-empty
    if state is None:
        start = b""
    elif isinstance(state, BitMapHistoryJournalState):
        start = state.to_bytes()
    else:
        # Canonical BitMapHistoryJournalState bytes, already validated.
        start = state  # type: ignore[assignment]
    candidate = BitMapHistoryJournalBundle(
        version=1,
        start=start,
        evidences=tuple(evidence.to_bytes() for evidence in coerced),
        end=final.to_bytes(),
        mac=b"\x00" * 32,
    )
    return replace(
        candidate,
        mac=_bit_map_history_journal_bundle_mac(key, candidate),
    )


def audit_map_history_journal_bundle(
    x: object, key: object
) -> "BitMapHistoryJournalState":
    """Re-verify a :class:`BitMapHistoryJournalBundle` against ``key``.

    ``x`` must be a :class:`BitMapHistoryJournalBundle` or its canonical
    :meth:`BitMapHistoryJournalBundle.to_bytes` encoding and ``key`` the
    non-empty shared ``bytes`` key — a wrong-typed argument raises
    :class:`TypeError`, every other contract violation raises
    :class:`ValueError`. The bundle MAC is recomputed as
    ``HMAC-SHA256(key, b"NPBJ3" + C)`` and compared in constant time, then
    the carried ``start`` (when non-empty) and ``end`` states are each
    checked at both MAC layers — the checkpoint table's ``NPBL1`` MAC and
    the state's own ``NPBJ1`` MAC — exactly as
    :class:`BitMapHistoryJournalAuditor` checks them. Finally the carried
    segments are replayed in order through a fresh auditor, starting from
    no journal state when ``start`` is empty and from the carried starting
    state otherwise, and the recomputed final state must equal the bundle's
    ``end`` byte for byte. Auditing is a pure check: it touches no auditor
    state beyond the throwaway replay and returns no partial result — on
    success the frozen :class:`BitMapHistoryJournalState` of the final
    journal is returned.
    """
    bundle = _coerce_bit_map_history_journal_bundle(x, "x")
    if not isinstance(key, bytes):
        raise TypeError("key must be bytes")
    if not key:
        raise ValueError("key must be non-empty")
    if not hmac.compare_digest(
        _bit_map_history_journal_bundle_mac(key, bundle), bundle.mac
    ):
        raise ValueError("bit map history journal bundle mac does not match")
    # Both MAC layers of the carried start and end states, always
    # recomputed before the replay is consulted.
    if bundle.start:
        BitMapHistoryJournalAuditor(key, state=bundle.start)
    BitMapHistoryJournalAuditor(key, state=bundle.end)
    auditor = BitMapHistoryJournalAuditor(
        key, state=bundle.start if bundle.start else None
    )
    for evidence in bundle.evidences:
        auditor.audit(evidence)
    final = auditor.state
    assert final is not None  # guaranteed: evidences is non-empty
    if final.to_bytes() != bundle.end:
        raise ValueError(
            "bit map history journal bundle end does not match the replayed"
            " journal"
        )
    return final


